// Aplana los campos personalizados de Kommo a algo legible.
const crudo = $input.first().json ?? {};
const l = crudo.data ?? crudo;
const campos = {};
for (const c of (l.custom_fields_values ?? [])) {
  const v = (c.values ?? [])[0] ?? {};
  let valor = v.value ?? v.enum_id ?? null;
  // Un campo de fecha vaciado se queda en 0, porque Kommo no acepta null ahi.
  // La fecha del evento ya es de texto y no pasa por aqui, pero quedan los
  // del equipo —«Apartado vence el», «Liquidado el»— y un 0 suelto se leeria
  // como el 1 de enero de 1970.
  if (c.field_type === 'date' && Number(valor) === 0) valor = null;
  campos[c.field_name] = valor;
}
const msg = $('formatear').first().json;
const rafaga = $('leer_rafaga').first().json;
return [{ json: {
  lead_id: String(l.id ?? msg.lead_id),
  etapa_id: l.status_id ?? null,
  responsable_id: l.responsible_user_id ?? null,
  presupuesto: l.price ?? 0,
  campos,
  // Todo lo que el cliente dijo en la rafaga, ya junto en un solo texto.
  chats: rafaga.chats ?? msg.texto,
  cuantos_mensajes: Number(rafaga.cuantos ?? 1),
  origen: msg.origen,
  autor: msg.autor,
  adjunto_tipo: msg.adjunto_tipo,
  adjunto_url: msg.adjunto_url,
}}];

// Convierte lo que entendio el Director en el PATCH de campos de Kommo.
//
// Solo el Director escribe en Kommo. Si cada agente parchara el mismo lead se
// pisarian entre ellos y no habria forma de saber quien puso que.
//
// Regla de oro: solo se escribe lo que el cliente DIJO. Un campo que el
// Director no pudo determinar se queda como esta. Sobrescribir con null
// borraria lo que una encargada capturo a mano.

const CAMPO = {
  salon: 352870,
  tipo_evento: 352872,
  // TEXTO, no fecha. El viejo 352874 era `date` y ya esta borrado.
  //
  // Un campo de fecha de Kommo no se puede vaciar desde el API: `values: []`
  // da TooFew, `null` da NotNullable, y lo unico que acepta es 0 — que la
  // ficha pinta «31/12/1969» y parece un sistema roto. Como el tipo de un
  // campo tampoco se puede cambiar, se creo uno nuevo de texto.
  //
  // El formato es «2027-03-20 (sábado)»: en ISO al principio para que
  // ordenar alfabeticamente sea ordenar cronologicamente, y el dia de la
  // semana al lado para quien lo lee en la ficha.
  fecha_evento: 611320,
  invitados: 352876,
};

// Los select de Kommo guardan enum_id, no texto.
const ENUM_SALON = {
  norma: 281622, esmeralda: 281624, santacruz: 281626, quetzal: 281628,
};
const ENUM_TIPO = {
  xv: 281630, boda: 281632, graduacion: 281634,
  posada: 281636, cumpleanos: 281638, babyshower: 281640,
};

// Del JSON del Director, aunque venga envuelto en cercos de codigo.
let salida = $json.output ?? '';
if (typeof salida === 'string') {
  salida = salida.trim().replace(/^```[a-z]*\s*/i, '').replace(/```\s*$/, '').trim();
  try { salida = JSON.parse(salida); } catch (e) { salida = {}; }
}
const datos = (salida && salida.datos) || {};

const valores = [];
const anotado = {};

if (ENUM_SALON[datos.salon]) {
  valores.push({ field_id: CAMPO.salon, values: [{ enum_id: ENUM_SALON[datos.salon] }] });
  anotado.salon = datos.salon;
}
if (ENUM_TIPO[datos.tipo_evento]) {
  valores.push({ field_id: CAMPO.tipo_evento, values: [{ enum_id: ENUM_TIPO[datos.tipo_evento] }] });
  anotado.tipo_evento = datos.tipo_evento;
}
// El modelo inventa el dia cuando el cliente solo dijo el mes: «diciembre de
// 2027» salio como 2027-12-01 y se escribio en Kommo. Por eso, ademas del
// formato, se exige que el numero del dia aparezca en lo que el cliente
// escribio. Si el dia venia arrastrado de un mensaje anterior, ese mensaje ya
// lo escribio en su turno, asi que no se pierde nada.
function dijoElDia(fecha, texto) {
  const dia = Number(fecha.slice(8, 10));
  const t = String(texto ?? '');
  if (new RegExp('(^|[^0-9])0?' + dia + '([^0-9]|$)').test(t)) return true;
  return dia === 1 && /\bprimero\b/i.test(t);
}

// Con acentos: esto lo copia el agente tal cual y sale al chat del cliente.
const DIA = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
const MES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio',
             'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];

// En español la fecha va «20 de marzo de 2027». «Marzo 20 de 2027» es orden
// de ingles y en el chat se nota raro.
function enLetras(iso) {
  const y = Number(iso.slice(0, 4)), m = Number(iso.slice(5, 7)), d = Number(iso.slice(8, 10));
  const dow = new Date(Date.UTC(y, m - 1, d)).getUTCDay();
  return `${DIA[dow]} ${d} de ${MES[m - 1]} de ${y}`;
}

// Hoy en Monterrey. Nunca el reloj del servidor: n8n corre en UTC y al cruzar
// la medianoche eso cambia que fechas cuentan como pasadas.
const HOY = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Monterrey', year: 'numeric', month: '2-digit', day: '2-digit',
}).format(new Date());

const esFechaReal = (iso) => {
  const [y, m, d] = iso.split('-').map(Number);
  const t = new Date(Date.UTC(y, m - 1, d));
  return t.getUTCFullYear() === y && t.getUTCMonth() === m - 1 && t.getUTCDate() === d;
};

/** El cliente escribio el anio, o lo puso el modelo de su cosecha? */
function dijoElAnio(fecha, texto) {
  return new RegExp('(^|[^0-9])' + fecha.slice(0, 4) + '([^0-9]|$)').test(String(texto ?? ''));
}

/**
 * El anio no se adivina: se pregunta.
 *
 * El cliente escribio «6 de marzo» y el modelo devolvio «2024-03-06»: un
 * miercoles de hace dos anios. Eso se escribio en Kommo como fecha del evento
 * y el agente se lo confirmo tan seguro —«tus XV serian el miercoles 6 de
 * marzo de 2024»— porque el dia de la semana SI era correcto. Un dato
 * inventado con un detalle verdadero al lado es el mas dificil de ver.
 *
 * La primera version de este guardia tomaba el proximo anio en que esa fecha
 * no hubiera pasado. Estaba mal, y lo dijo el Lic.: «10 de diciembre» puede
 * ser 2026 o 2027, y entre uno y otro cambia el escalon de anticipacion —o
 * sea, el precio. Adivinar bien la mitad de las veces es cotizar mal la otra
 * mitad, y el cliente se entera tarde.
 *
 * Asi que cuando el anio no esta en lo que el cliente escribio, aqui no sale
 * ninguna fecha: sale el aviso de que falta, con los dos anios concretos que
 * el agente tiene que ofrecerle.
 */
function anios(mesDia, cuantos = 2) {
  const out = [];
  const desde = Number(HOY.slice(0, 4));
  for (let y = desde; y <= desde + 5 && out.length < cuantos; y++) {
    const cand = `${y}-${mesDia}`;
    // El 29 de febrero no existe todos los anios: se ofrecen los que si.
    if (esFechaReal(cand) && cand >= HOY) out.push(y);
  }
  return out;
}

let fechaDicha = null;   // la fecha buena, lista para Kommo
let faltaAnio = null;    // «10 de diciembre», con los anios que se le ofrecen
let fechaPasada = null;  // el cliente escribio un anio que ya paso

const loQueDijo = $('formatLead').first().json.chats;

/**
 * El cliente esta hablando de una VISITA, no de su evento.
 *
 * «Me gustaria ir a conocer Esmeralda el sabado 24 de octubre» y el Director
 * devolvio eso como `fecha_evento`. Si el cliente hubiera dicho el anio, esa
 * fecha se habria escrito en Kommo encima de la del evento —en esa misma
 * conversacion la boda era el 12 de junio de 2027— y nadie se entera hasta
 * que alguien cotiza con la fecha equivocada.
 *
 * El prompt del Director ya lo dice; esto es el seguro. Se pide que hable de
 * visita Y que no nombre el evento, para no tragarse un «quiero ir a conocerlo
 * antes de mi boda del 20 de marzo», donde la fecha SI es la del evento.
 */
const HABLA_DE_VISITA = /\b(ir a conocer|visitar|pasar a ver|conocer el sal[oó]n|agendar (una )?(cita|visita)|hacer (una )?cita)\b/i;
const NOMBRA_EL_EVENTO = /\b(mi|nuestra|la) (boda|fiesta|evento|celebraci[oó]n|xv|quince)\b|\bes para\b/i;
const esVisita = HABLA_DE_VISITA.test(loQueDijo) && !NOMBRA_EL_EVENTO.test(loQueDijo);

/**
 * El cliente contesta solo el anio a la pregunta de arriba.
 *
 * «10 de diciembre» -> se le pregunta 2026 o 2027 -> contesta «2027». En ese
 * mensaje ya no esta el dia, asi que el guardia del dia lo rechazaba y la
 * fecha no llegaba nunca a Kommo: el agente cotizaba bien de memoria y el
 * lead se quedaba vacio.
 *
 * Se acepta cuando el anio SI esta escrito y el dia no es 1. Ese 1 es la
 * frontera: es lo que el modelo pone cuando el cliente solo dijo el mes
 * —«diciembre de 2027» -> 2027-12-01—, que es justo lo que no queremos dar
 * por bueno. A cambio, quien de verdad quiera el dia 1 tendra que decirlo una
 * segunda vez; sale mas barato que guardar un dia inventado.
 */
function contestoElAnio(iso, texto) {
  return !dijoElDia(iso, texto)
    && dijoElAnio(iso, texto)
    && Number(iso.slice(8, 10)) !== 1;
}

if (!esVisita
    && /^\d{4}-\d{2}-\d{2}$/.test(datos.fecha_evento ?? '')
    && esFechaReal(datos.fecha_evento)
    && (dijoElDia(datos.fecha_evento, loQueDijo)
        || contestoElAnio(datos.fecha_evento, loQueDijo))) {
  const iso = datos.fecha_evento;
  const mesDia = iso.slice(5);
  if (!dijoElAnio(iso, loQueDijo)) {
    faltaAnio = {
      dia_mes: `${Number(iso.slice(8, 10))} de ${MES[Number(iso.slice(5, 7)) - 1]}`,
      opciones: anios(mesDia),
    };
  } else if (iso < HOY) {
    fechaPasada = enLetras(iso);
  } else {
    fechaDicha = iso;
  }
}

if (fechaDicha) {
  // Ya no va como epoch: el campo es de texto. De paso se acabo la clase de
  // error mas tonta que tenia esto — guardar a medianoche UTC hacia que en
  // Monterrey (UTC-6) la ficha mostrara el dia anterior.
  valores.push({
    field_id: CAMPO.fecha_evento,
    values: [{ value: `${fechaDicha} (${enLetras(fechaDicha).split(' ')[0]})` }],
  });
  anotado.fecha_evento = fechaDicha;
}
// ─────────────────────────────────────────────────────────────────────────
// La fecha, ya con su dia de la semana, lista para que el agente la nombre.
//
// El Lic. quiere que nunca se diga «el 20 de marzo» a secas, sino «el sabado
// 20 de marzo». Pero esto NO se le puede pedir al prompt: sacar el dia de la
// semana de una fecha es aritmetica, y el modelo la falla sin avisar. Peor
// aun, la falla con seguridad — diria «viernes 20 de marzo» con el mismo tono
// con que dice el precio, y el cliente le cree.
//
// Asi que se calcula aqui y se le entrega hecha. El modelo solo la copia.

// SOLO la fecha de este mensaje. El campo del lead no entra aqui.
//
// Antes si entraba, como respaldo para no perder el dia de la semana cuando
// el cliente escribia «¿y cuanto sale?». Ese respaldo acabo diciendo una
// mentira: tras un «/*» la memoria queda limpia pero el campo del lead no
// —Kommo no deja vaciar una fecha—, asi que el agente leia esa fecha vieja y
// se la afirmaba al cliente como suya: «tus XV para el sabado 13 de marzo de
// 2027», cuando nadie habia dicho ninguna fecha en toda la conversacion.
//
// No hacia falta ese respaldo: cuando el agente cotiza, `cotizar` le devuelve
// `dia_semana` y `fecha_especial` de esa misma fecha, y mientras conversa la
// tiene en su propia memoria. Lo unico que aportaba era afirmar lo que nadie
// dijo.
const fechaISO = fechaDicha;

// El tramo de tarifa mas chico que existe es de 50 personas: por debajo de
// ahi no hay nada que cotizar en ningun salon ni ningun paquete.
//
// Sirve de guardia de dos cosas a la vez. Un numero asi de bajo casi nunca es
// la cantidad de invitados: «quisiera cotizar unos 15» son unos XV anos, y el
// Director lo leyo como quince invitados — luego el agente pregunto «de que
// tipo de evento se trata? tus XV anos, boda...» justo despues de que se lo
// dijeran. Y cuando SI son invitados de verdad, lo que toca no es callarse,
// es decirle que el minimo son 50.
const MINIMO_INVITADOS = 50;
const invitados = Number(datos.invitados);
let invitadosBajos = null;
if (Number.isFinite(invitados) && invitados >= MINIMO_INVITADOS) {
  valores.push({ field_id: CAMPO.invitados, values: [{ value: invitados }] });
  anotado.invitados = invitados;
} else if (Number.isFinite(invitados) && invitados > 0) {
  invitadosBajos = invitados;
}

// El interruptor ya no se escribe desde aqui. Cuando el campo se llamaba «IA
// activa» habia que marcarlo en el primer contacto, porque Kommo omite los
// checkbox sin marcar y sin marcarlo no se podia distinguir «nadie lo ha
// tocado» de «la encargada lo apago».
//
// Ahora se llama «Stop IA» y la ausencia significa lo correcto por si sola:
// sin marcar, la IA corre. Marcarlo seria justo lo contrario de lo que se
// quiere en un lead nuevo.

return [{
  json: {
    hay_datos: valores.length > 0,
    lead_id: $('formatLead').first().json.lead_id,
    anotado,
    // Lo acumulado de la conversacion, para que el turno sepa que NO hay que
    // volver a preguntar. `anotado` solo trae lo de este mensaje.
    campos: $('formatLead').first().json.campos ?? {},
    fecha_iso: fechaISO,
    fecha_larga: fechaISO ? enLetras(fechaISO) : null,
    // Dijo el dia y el mes pero no el anio. No se supone ninguno: el agente
    // pregunta, con estas dos opciones concretas.
    falta_anio: faltaAnio,
    // Un numero de invitados por debajo del minimo que se puede cotizar.
    invitados_bajos: invitadosBajos,
    // Escribio un anio que ya paso. Tampoco se da por bueno.
    fecha_pasada: fechaPasada,
    cuerpo: { custom_fields_values: valores },
  },
}];

// Parte la respuesta del agente en las piezas que espera enviar_mensaje_salones.
//
// Se hace con codigo y no con otro agente a proposito: partir en frontera de
// parrafo es una regla, no un juicio. Un modelo haciendo esto cuesta, tarda, y
// algun dia devuelve algo distinto para el mismo texto.
const bruto = $json.output ?? '';
let texto = typeof bruto === 'string' ? bruto : JSON.stringify(bruto);

// El modelo a veces envuelve la respuesta en cercos de codigo o en un JSON.
texto = texto.trim().replace(/^```[a-z]*\s*/i, '').replace(/```\s*$/, '').trim();
if (texto.startsWith('{')) {
  try {
    const o = JSON.parse(texto);
    texto = o.respuesta ?? o.parte1 ?? o.output ?? texto;
  } catch (e) { /* no era JSON: se queda con el texto tal cual */ }
}

// El agente ve las URL de las laminas dentro de la respuesta de `cotizar` y
// se le ha dado por pegarlas en el texto en markdown:
//
//   «Aqui te dejo la imagen: ![Paquete Bronce](https://kommo.cc/K/YG9FBW/...)»
//
// Al cliente le llega el corchetazo crudo Y la foto adjunta, duplicado y feo.
// Se quita aqui y no solo en el prompt porque el prompt es una peticion y
// esto es una garantia: las fotos las adjunta el sistema, no se escriben.
function quitarEnlacesDeImagen(t) {
  return t
    // ![lo que sea](url)  y  [lo que sea](url de kommo)
    .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
    .replace(/\[[^\]]*\]\(https?:\/\/(?:kommo\.cc|drive-[a-z0-9-]+\.kommo\.com)[^)]*\)/gi, '')
    // y la URL suelta, sin markdown
    .replace(/https?:\/\/(?:kommo\.cc|drive-[a-z0-9-]+\.kommo\.com)\S*/gi, '')
    // la frase que los presentaba se queda colgando con dos puntos al aire:
    // «Aqui te dejo la imagen:» sin nada detras.
    .replace(/[^\S\r\n]*:[^\S\r\n]*(?=\r?\n|$)/g, '')
    .replace(/[^\S\r\n]{2,}/g, ' ')
    .replace(/(\r?\n){3,}/g, '\n\n')
    .trim();
}
texto = quitarEnlacesDeImagen(texto);

const MAX_PARTES = 2;   // por ahora dos; el subflujo admite hasta cuatro

// Se corta por ritmo de WhatsApp, no por longitud: la informacion en un
// mensaje y la pregunta de cierre en otro. Antes se cortaba a los 600
// caracteres, pero una cotizacion tipica ronda los 400 — con esa regla el
// corte en dos casi nunca se activaba.
//
// Nunca se corta a media frase: si no hay frontera de parrafo, va entera. Un
// mensaje largo de una sola pieza molesta menos que uno partido a la mitad.
function partir(t) {
  const parrafos = t.split(/\n\s*\n/).map((x) => x.trim()).filter(Boolean);
  if (parrafos.length < 2) return [t];
  // El ultimo parrafo se va solo: en las respuestas de Maya es la invitacion
  // a visitar o la pregunta. Lo anterior se junta en el primer mensaje.
  return [parrafos.slice(0, -1).join('\n\n'), parrafos[parrafos.length - 1]]
    .slice(0, MAX_PARTES);
}

const partes = partir(texto);
const fl = $('formatLead').first().json;


return [{
  json: {
    cuantas_partes: partes.length,
    parte1: partes[0] ?? '',
    parte2: partes[1] ?? '',
    parte3: '',
    parte4: '',
    lead_id: fl.lead_id,
    // La pone elegir_lamina, el nodo siguiente: aqui no se puede leer la
    // salida de `cotizar` porque un Code no alcanza a un nodo-herramienta.
    imagen_url: '',
    mensaje_cliente: fl.chats,
    // Declarados en el subflujo pero sin usar en su codigo: van en cero para
    // no mover ninguna etapa por accidente.
    proximo_paso: 0,
    status_id: 0,
    // Que agente redacto. Se guarda aqui porque despues de este nodo
    // $prevNode.name ya seria 'formatear_respuesta'.
    agente: $prevNode.name,
    texto_completo: texto,
  },
}];

// Decide qué láminas acompañan a la respuesta, y las pega al resto del envío.
//
// Esto NO lo hace el modelo. Si tuviera que copiar una URL de 80 caracteres,
// tarde o temprano se le cae uno — y una URL rota no da error: el mensaje sale
// sin foto y la ejecución queda en verde.
//
// Tampoco se lee de `cotizar`, aunque sea quien ya trae la lámina: un nodo
// Code no puede alcanzar un nodo conectado como herramienta. Por eso el
// catálogo entero llega por el camino principal, desde /api/imagenes, y el
// cruce se hace aquí.
//
// Si el agente ofrece tres salones, van las tres láminas. Antes iba una sola
// —la del salón que quedaba más cerca del nombre del paquete— y el cliente
// veía la hoja de uno y el precio de tres.

// Las laminas van con la cotizacion y son como mucho una por salon ofrecido.
const MAX_LAMINAS = 3;
// Las fotos del salon son otra cosa: el Lic. las quiere a montones, que es
// como se ensena un lugar. Diez mensajes seguidos, uno por foto, porque Kommo
// adjunta una imagen por plantilla.
const MIN_FOTOS = 10;
const MAX_FOTOS = 12;

const limpiar = (s) => String(s ?? '').toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '');
const sinEventos = (s) => limpiar(s).replace(/\s*eventos\s*$/, '').trim();

const resp = $('formatear_respuesta').first().json;
const fl = $('formatLead').first().json;

// Todos los salones, tengan lámina o no: reconocer el nombre de uno que aún
// no tiene foto es justo lo que evita mandarle la de otro.
const salonesTodos = [...new Set(($json.salones ?? [])
  .map((s) => sinEventos(s.nombre || s.clave)).filter(Boolean))];

// Una entrada por paquete y salón; dentro, sus láminas. Un paquete puede
// tener varias: el de «Baby Shower, Despedidas de Soltera y Bautizos» se
// cotiza igual para los tres, pero el arte lo parte en tres.
const grupos = new Map();
for (const l of ($json.laminas ?? [])) {
  const clave = l.paquete + '|' + l.salon;
  if (!grupos.has(clave)) {
    grupos.set(clave, {
      salon_texto: sinEventos(l.salon_nombre || l.salon),
      paquete_texto: limpiar(l.paquete).replace(/^paquete\s+/, '').trim(),
      // Los nombres tal cual, para el pie de foto.
      salon_nombre: l.salon_nombre || l.salon,
      paquete_nombre: l.paquete,
      imagenes: [],
    });
  }
  grupos.get(clave).imagenes.push({ etiqueta: l.etiqueta, url: l.url });
}

// Las fotos de cortesia, por salon. Cada una trae sus pistas: como la nombra
// el cliente, que no es como la nombra el catalogo —nadie escribe «arreglos de
// mesa en prestamo», escriben «centros de mesa»—.
const cortesias = ($json.cortesias ?? []).map((c) => ({
  salon_texto: sinEventos(c.salon_nombre || c.salon),
  url: c.url,
  pistas: String(c.pistas ?? c.titulo ?? '').split(',')
    .map((x) => limpiar(x).trim()).filter(Boolean),
}));

/** Todas las posiciones donde aparece `aguja` en `t`, como palabra entera. */
function posiciones(t, aguja) {
  if (!aguja) return [];
  const esc = aguja.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const re = new RegExp('(^|[^a-z0-9])' + esc + '([^a-z0-9]|$)', 'g');
  const out = [];
  let m;
  while ((m = re.exec(t)) !== null) {
    out.push(m.index + m[1].length);
    re.lastIndex = m.index + 1;   // permite solapes
  }
  return out;
}

// Palabras que no distinguen un paquete de otro, asi que no sirven de apodo.
const RELLENO = new Set(['paquete', 'de', 'del', 'la', 'las', 'el', 'los', 'y',
  'boda', 'bodas', 'xv', 'para', 'con', 'o', 'u']);

// Un salón que se acaba de descartar no lleva lámina. «El salón Norma ya está
// ocupado ese día, pero tengo Esmeralda y Santa Cruz con el Paquete Bronce»:
// sin esto, Norma queda pegadísimo a «Bronce» y se cuela su hoja — la del
// único salón que el cliente NO puede tener.
const DESCARTADO = /ocupad|no (esta|está) disponible|no tengo|ya no (hay|queda)|no (hay|queda) (lugar|espacio|disponibilidad)/;
function estaDescartado(t, pos, largo) {
  return DESCARTADO.test(t.slice(pos, pos + largo + 45));
}

// Los paquetes que existen en cada salón. Se busca solo entre los suyos, y no
// entre todos, porque los nombres se solapan: Quetzal llama al suyo «Paquete
// Plata Boda y XV» y los demás «Paquete Plata». Buscando en la bolsa común,
// el «plata» de Esmeralda empataba en la misma posición y ganaba el desempate
// — quedaba el par quetzal+plata, que no existe, y Quetzal se iba sin lámina.
const paquetesDe = new Map();
for (const g of grupos.values()) {
  if (!g.paquete_texto) continue;
  if (!paquetesDe.has(g.salon_texto)) paquetesDe.set(g.salon_texto, new Set());
  paquetesDe.get(g.salon_texto).add(g.paquete_texto);
}

/**
 * Los apodos con que se puede reconocer un paquete dentro de su salón.
 *
 * El nombre exacto no basta: el catálogo dice «Paquete Plata Boda y XV» y el
 * agente escribe «el Paquete Plata para boda». Son el mismo, y por una
 * preposición Quetzal se quedaba sin lámina.
 *
 * Un apodo es una palabra suya que **ningún otro paquete de ese salón usa**.
 * «plata» vale porque en Quetzal solo hay uno con plata; «día» no vale en
 * Esmeralda, que tiene el del Día de las Madres y el del Día del Maestro —
 * ahí los que distinguen son «madres» y «maestro».
 */
const apodosDe = new Map();
for (const [salon, paquetes] of paquetesDe) {
  const cuenta = new Map();
  const palabras = new Map();
  for (const p of paquetes) {
    const ws = [...new Set(p.split(/[^a-z0-9]+/).filter(
      (x) => x.length >= 3 && !RELLENO.has(x)))];
    palabras.set(p, ws);
    for (const w of ws) cuenta.set(w, (cuenta.get(w) ?? 0) + 1);
  }
  const m = new Map();
  for (const p of paquetes) {
    m.set(p, [p, ...palabras.get(p).filter((w) => cuenta.get(w) === 1 && w !== p)]);
  }
  apodosDe.set(salon, m);
}

/** Los pares salón+paquete nombrados DENTRO de un mismo párrafo. */
function paresDelParrafo(t) {
  const marcasSalon = [];
  for (const s of salonesTodos) {
    for (const p of posiciones(t, s)) marcasSalon.push({ salon: s, pos: p, largo: s.length });
  }
  marcasSalon.sort((a, b) => a.pos - b.pos);

  const pares = [];
  for (const ms of marcasSalon) {
    if (estaDescartado(t, ms.pos, ms.largo)) continue;
    let mejor = null;
    for (const [paquete, apodos] of (apodosDe.get(ms.salon) ?? new Map())) {
      for (const apodo of apodos) {
        for (const pos of posiciones(t, apodo)) {
          const d = Math.abs(pos - ms.pos);
          // A igual distancia gana el apodo más largo: «plata boda y xv»
          // empieza donde «plata», y el que describe mejor es el largo.
          if (!mejor || d < mejor.d || (d === mejor.d && apodo.length > mejor.largo)) {
            mejor = { paquete, d, largo: apodo.length };
          }
        }
      }
    }
    if (mejor) pares.push({ salon: ms.salon, paquete: mejor.paquete });
  }
  return pares;
}

/**
 * Los pares salón+paquete que el agente ofreció, en el orden en que aparecen.
 *
 * Se busca **párrafo por párrafo**, y esa es toda la gracia. Dentro de un
 * párrafo, cada salón se empareja con el nombre de paquete más cercano:
 * «Esmeralda y Santa Cruz, cada uno con el Paquete Bronce» son dos pares, y
 * «También está Quetzal con el Paquete Plata» es otro.
 *
 * Buscando en el texto entero se cruzaban los párrafos y salía mal:
 *
 *   «Norma ya está ocupado, pero Esmeralda, Santa Cruz y Quetzal están libres.
 *
 *    Te cotizo Esmeralda... El Paquete Bronce cuesta $59,400.»
 *
 * Ahí Santa Cruz se pegaba al «Bronce» del párrafo siguiente y se mandaba su
 * hoja —con OTRO precio— para un salón que solo se habia mencionado como
 * libre. Nombrar un salón no es ofrecerlo; ofrecerlo es decir qué paquete y
 * cuánto, y eso pasa en la misma frase.
 */
function paresDelTexto(t) {
  const pares = [];
  const vistos = new Set();

  // Si en todo el mensaje hay UN solo salon, no hay nada que desambiguar: los
  // paquetes que nombre son suyos, esten en el parrafo que esten. La regla de
  // parrafo existe para cuando compiten varios, y aplicarla igual aqui dejaba
  // sin lamina lo mas comun de todo —«tus XV en Santa Cruz...» en un parrafo y
  // «el Paquete Bronce cuesta $60,400» en el siguiente.
  const unicos = [...new Set(salonesTodos.filter((x) => x && t.includes(x)))];
  if (unicos.length === 1) {
    const salon = unicos[0];
    if (!posiciones(t, salon).some((p) => estaDescartado(t, p, salon.length))) {
      for (const par of paresDelParrafo(t.replace(/\n\s*\n/g, ' '))) {
        const clave = par.salon + '|' + par.paquete;
        if (vistos.has(clave)) continue;
        vistos.add(clave);
        pares.push(par);
      }
      return pares;
    }
  }

  for (const parrafo of t.split(/\n\s*\n/)) {
    for (const par of paresDelParrafo(parrafo)) {
      const clave = par.salon + '|' + par.paquete;
      if (vistos.has(clave)) continue;
      vistos.add(clave);
      pares.push(par);
    }
  }
  return pares;
}

/** De un grupo con varias láminas, la que toca según lo que escribió el cliente. */
function deEseGrupo(g) {
  if (g.imagenes.length === 1) return g.imagenes[0].url;
  // El arte parte dos paquetes en varias laminas: «Baby Shower, Despedidas de
  // Soltera y Bautizos» en tres, y «Aniversarios / Cumpleanos» en dos. El
  // precio y el contenido son los mismos; lo que cambia es a quien se le
  // enseña, asi que lo decide lo que escribio el cliente.
  const PISTA = {
    bautizo:     /bautiz/,
    despedida:   /despedida/,
    babyshower:  /baby ?shower/,
    aniversario: /aniversario|bodas? de (plata|oro|plomo)/,
    cumpleanos:  /cumplea|cumple/,
  };
  const dicho = limpiar(fl.chats);
  for (const img of g.imagenes) {
    const re = PISTA[img.etiqueta];
    if (re && re.test(dicho)) return img.url;
  }
  return '';
}

function laminas() {
  const t = limpiar(resp.texto_completo);
  if (!t) return [];
  const out = [];
  for (const par of paresDelTexto(t)) {
    const g = [...grupos.values()].find(
      (x) => x.salon_texto === par.salon && x.paquete_texto === par.paquete);
    if (!g) continue;
    const url = deEseGrupo(g);
    // Ante cualquier duda, ese par se va sin imagen. La lámina equivocada el
    // cliente la lee como la oferta.
    if (!url) continue;
    out.push({ url, pie: `${g.paquete_nombre} · ${g.salon_nombre}` });
    if (out.length === MAX_LAMINAS) break;
  }
  return out;
}

// Cuando se cotiza mandan SIEMPRE las laminas del paquete. Es la unica regla
// que importa de las dos: el agente nombra las cortesias dentro de la propia
// cotizacion —«incluye el Espejo de Bienvenida, el Aro iluminado...»—, asi que
// sin esta prioridad una cotizacion acabaria mandando la foto de una cortesia
// en lugar de la hoja del paquete, que es la que trae el precio.
//
// La foto de una cortesia es para el otro momento: cuando el cliente pregunta
// por una cosa concreta y no se esta cotizando. Ahi la foto vale mas que
// cualquier descripcion.
function cortesia() {
  const dicho = limpiar(fl.chats);
  if (!dicho) return [];
  const t = limpiar(resp.texto_completo);

  // Para una cortesia hace falta saber de que salon se habla, y aqui no hay
  // paquete cerca con que desempatar: si el texto nombra dos, no se adivina.
  const nombrados = salonesTodos.filter((x) => x && t.includes(x));
  const salon = nombrados.length === 1
    ? nombrados[0]
    : (nombrados.length ? null : sinEventos(fl.campos?.['Salón']) || null);
  if (!salon) return [];

  // Tiene que haberla preguntado EL CLIENTE. Buscarla en lo que escribio el
  // agente daria falsos positivos todo el tiempo, porque las enumera al cotizar.
  const encajan = cortesias.filter((c) => c.salon_texto === salon
    && c.pistas.some((pi) => dicho.includes(pi)));

  // Preguntó por dos: no se adivina cual queria ver.
  const distintas = [...new Set(encajan.map((c) => c.url))];
  return distintas.length === 1 ? [{ url: distintas[0], pie: '' }] : [];
}

// Las fotos del salon: como se ve el lugar.
//
// Van DESPUES de la lamina del paquete, cuando el cliente dijo que si quiere
// verlas. El disparo es la frase con la que Maya las anuncia —«te paso unas
// fotos del salon»—, igual que la lamina se dispara con el paquete que
// nombra. Lo que ella no decide nunca es CUALES: eso sale del orden que tenga
// el salon en el panel.
const ANUNCIA_FOTOS =
  /\b(te (paso|mando|comparto|envio|dejo)|aqui (te dejo|van)|mira)\b[^.]{0,40}\b(fotos?|imagenes?)\b/;

function fotosDelSalon() {
  const t = limpiar(resp.texto_completo);
  if (!t || !ANUNCIA_FOTOS.test(t)) return [];

  const nombrados = salonesTodos.filter((x) => x && t.includes(x));
  // Si nombra dos salones no se adivina de cual las queria ver; si no nombra
  // ninguno, el del lead sirve: lo escribio el Director cuando el cliente lo
  // dijo.
  const salon = nombrados.length === 1
    ? nombrados[0]
    : (nombrados.length ? null : sinEventos(fl.campos?.['Salón']) || null);
  if (!salon) return [];

  const suyas = ($json.fotos ?? [])
    .filter((f) => sinEventos(f.salon_nombre || f.salon) === salon)
    .slice(0, MAX_FOTOS);

  // El pie: el titulo que le haya puesto la encargada en el panel y, si no
  // tiene, «3 de 10». Antes todas decian «Mira también esta.», diez veces
  // seguidas — repetir la misma frase diez veces no es una conversacion, es
  // un robot. El contador al menos dice cuantas faltan.
  return suyas.map((f, i) => ({
    url: f.url,
    pie: f.titulo || `${i + 1} de ${suyas.length}`,
    esFoto: true,
  }));
}

let fotos = [];
try {
  // La cotizacion manda sobre todo lo demas: si hay lamina, va la lamina.
  fotos = laminas();
  if (!fotos.length) fotos = cortesia();
  if (!fotos.length) fotos = fotosDelSalon();
} catch (e) { fotos = []; }

// ── repartir las fotos entre las partes del mensaje ────────────────────────
//
// Kommo adjunta UNA imagen por plantilla, asi que diez fotos son diez
// mensajes. La primera viaja con el texto del agente; las demas van detras,
// cada una con su pie.
const partes = [resp.parte1, resp.parte2, resp.parte3, resp.parte4]
  .filter((x) => x && String(x).trim());
const porParte = partes.map((_, i) => (i === 0 && fotos.length ? fotos[0].url : ''));

// La ULTIMA foto se queda con la pregunta de cierre, y por eso se le quita
// aqui al bloque de texto: diez fotos detras de la pregunta la entierran, y
// el cliente se queda mirando fotos sin saber que se esperaba de el.
const cierre = fotos.length > 1 && partes.length > 1 ? partes.pop() : null;
if (cierre) porParte.pop();

for (const [i, foto] of fotos.slice(1).entries()) {
  const ultima = i === fotos.length - 2;
  partes.push(ultima && cierre ? cierre : foto.pie);
  porParte.push(foto.url);
}

// Si no habia pregunta que mover —el agente mando un solo parrafo— se le
// pone una: diez fotos sin nada detras dejan la conversacion muerta.
if (fotos.length > 1 && !cierre && fotos[0].esFoto) {
  partes.push('¿Qué te parece el salón?');
  porParte.push('');
}

return [{
  json: {
    ...resp,
    cuantas_partes: partes.length,
    // Se mantienen las cuatro sueltas por compatibilidad; de la quinta en
    // adelante solo viajan en `partes`.
    parte1: partes[0] ?? '',
    parte2: partes[1] ?? '',
    parte3: partes[2] ?? '',
    parte4: partes[3] ?? '',
    partes: JSON.stringify(partes),
    // Se mantiene por si algo viejo la lee; la que manda es `imagenes`.
    imagen_url: fotos[0]?.url ?? '',
    // Alineada con las partes: la posicion i es la foto de la parte i+1.
    imagenes: JSON.stringify(porParte),
  },
}];

// Lo que hay que hacer en Kommo cuando alguien manda «/*».
//
// Borrar la memoria sola no alcanza: el Director lee los campos del lead y
// arrastra la fecha y el salon de la conversacion anterior, asi que el
// «empezamos de cero» era mentira a medias.
//
// Pero esto borra datos de verdad, y ya paso en otro cliente: un «/*» cayo en
// un lead que resulto ser una clienta real y le limpio los campos en plena
// cotizacion. Por eso ANTES de borrar se deja una nota en el lead con lo que
// habia. Si alguna vez vuelve a pasar, el dato se recupera leyendo la nota en
// vez de reconstruirlo preguntandole al cliente.

const CAMPO = {
  salon: 352870,
  tipo_evento: 352872,
  fecha_evento: 611320,   // el de TEXTO; ver armar_patch_kommo.js
  invitados: 352876,
  paquete: 352880,
};

// Lo que NO se toca, a proposito:
//   352882 «Stop IA»        — si la encargada apago la IA, un /* no la puede
//                             volver a encender. Seria lo contrario de lo que
//                             quiso quien la apago.
//   352884 «Estado de contacto» — es operativo del equipo, no del agente.

const lead = $('formatLead').first().json;
const campos = lead.campos ?? {};

// El nombre que Kommo le da a cada campo, para leer lo que habia. Se mira por
// nombre porque es lo que trae `formatLead`, ya aplanado.
const NOMBRE = {
  'Salón': 'Salón',
  'Tipo de evento': 'Tipo de evento',
  'Fecha del evento': 'Fecha del evento',
  'Invitados': 'Invitados',
  'Paquete cotizado': 'Paquete cotizado',
};

// Ya no hay que traducir epochs: la fecha es texto y se lee tal cual. Antes
// esto convertia «1797055200» a algo legible, porque una nota con ese numero
// no le sirve a nadie.
const comoTexto = (_nombre, valor) =>
  (valor === null || valor === undefined || valor === '' ? null : String(valor));

// La clave es como se llama el campo en Kommo; el valor, como se escribe en
// la nota. Hoy coinciden todas, pero se mantienen separadas: el nombre del
// campo se cambia desde Kommo sin avisar a nadie.
const habia = [];
for (const [enKommo, etiqueta] of Object.entries(NOMBRE)) {
  const t = comoTexto(enKommo, campos[enKommo]);
  if (t !== null) habia.push(`${etiqueta}: ${t}`);
}

const nota = habia.length
  ? 'Se reinició la conversación con «/*». Los campos quedaron en blanco. '
    + 'Lo que había antes:\n' + habia.join('\n')
  : 'Se reinició la conversación con «/*». El lead no tenía datos capturados.';

// Vaciar un campo en Kommo es mandarlo con `{ value: null }`. Sirve en texto,
// numero y select, que son los cuatro que quedan; `values: []` lo rechaza
// siempre, con «TooFew: exactly 1 element».
const cuerpo = {
  custom_fields_values: Object.values(CAMPO).map((field_id) => ({
    field_id, values: [{ value: null }],
  })),
};

return [{
  json: {
    lead_id: lead.lead_id,
    tenia_datos: habia.length > 0,
    nota,
    cuerpo,
  },
}];

// La linea «[Sistema]» que acompaña al mensaje del cliente.
//
// Junta dos cosas que el agente no puede deducir y que necesita ANTES de
// cotizar: el dia de la semana de la fecha, y si ese dia tiene algo que
// avisar.
//
// Lo de Semana Santa vivia solo dentro de `cotizar`, asi que mientras el
// agente seguia recabando invitados la fecha pasaba sin que nadie dijera
// nada. El cliente decia «27 de marzo», ella confirmaba tan tranquila, y el
// aviso llegaba dos mensajes despues o no llegaba.

const p = $('armar_patch').first().json;

// La consulta al panel va en «continuar aunque falle»: si el panel no
// contesta, se pierde el aviso de la fecha especial pero la conversacion
// sigue. Quedarse mudo seria peor que no avisar.
let especial = null;
try {
  const r = $input.first().json ?? {};
  especial = r.fecha_especial ?? null;
} catch (e) { especial = null; }

const partes = [];

// Lo que el Director ya entendio, dicho con todas sus letras.
//
// Sin esto el agente solo ve el texto crudo y vuelve a interpretarlo por su
// cuenta, a veces peor: el cliente escribio «quisiera cotizar unos 15», el
// Director lo normalizo bien a XV anos, y el agente —que no lo veia— contesto
// «¿para que tipo de evento serian esos 15 invitados?». Preguntar por algo que
// el cliente acaba de decir es lo que mas cara de tonto le pone.
const EVENTO = {
  xv: 'unos XV años', boda: 'una boda', graduacion: 'una graduación',
  posada: 'una posada', cumpleanos: 'un cumpleaños', babyshower: 'un baby shower',
};
const SALON = {
  norma: 'Norma Eventos', esmeralda: 'Esmeralda Eventos',
  santacruz: 'Santa Cruz Eventos', quetzal: 'Quetzal Eventos',
};
// Lo de este turno manda sobre lo que ya estaba guardado en el lead, que es
// lo acumulado de la conversacion. `anotado` solo trae lo que se dijo AHORA.
const a = p.anotado ?? {};
const guardado = p.campos ?? {};
const tipo = a.tipo_evento ?? (guardado['Tipo de evento'] ? String(guardado['Tipo de evento']).toLowerCase() : null);
const salon = a.salon ?? (guardado['Salón'] ? String(guardado['Salón']) : null);
const cuantos = a.invitados ?? (Number(guardado['Invitados']) || null);

const sabido = [];
if (tipo) sabido.push(`es ${EVENTO[tipo] ?? tipo}`);
if (salon) sabido.push(`el salón es ${SALON[salon] ?? salon}`);
if (cuantos) sabido.push(`son ${cuantos} invitados`);

// Y lo que NO ha dicho, dicho tambien. Sin esta mitad el agente rellena el
// hueco con lo que encuentre en el texto: con «quisiera cotizar unos 15» dio
// por hecho que eran quince invitados y contesto «tus XV años para unos 15
// invitados». El 15 era el evento, no la gente.
const faltan = [];
if (!tipo) faltan.push('qué tipo de evento es');
if (!cuantos) faltan.push('cuántos invitados son');

if (sabido.length) {
  partes.push(`Esto ya lo dijo el cliente y NO se lo vuelvas a preguntar: ${sabido.join(', ')}.`
    + (faltan.length ? ` Y esto NO lo ha dicho todavía, así que no te lo inventes: ${faltan.join(' ni ')}.` : ''));
}

// Dijo el dia y el mes, pero no el anio. No se elige por el: «10 de
// diciembre» puede ser 2026 o 2027, y entre uno y otro cambia el escalon de
// anticipacion, o sea el precio. Se pregunta, con los dos anios concretos en
// la mano para que no tenga que calcularlos.
if (p.falta_anio) {
  const op = (p.falta_anio.opciones ?? []).join(' o ');
  partes.push(`El cliente dijo «${p.falta_anio.dia_mes}» pero NO dijo el anio. `
    + 'No lo supongas y no cotices todavia: preguntale de que anio '
    + (op ? `—${op}—` : '') + ' y espera a que te conteste. '
    + 'El precio depende de cuantos meses falten, asi que con el anio '
    + 'equivocado la cotizacion entera sale mal.');
}

// Un numero demasiado chico para ser invitados. Casi siempre es otra cosa
// —«unos 15» son XV anos— y cuando de verdad son invitados, hay que decirle
// el minimo en vez de callarse.
if (p.invitados_bajos) {
  partes.push(`El cliente dijo el numero ${p.invitados_bajos}, que NO se guardo como `
    + 'invitados: el minimo que se puede cotizar son 50 personas. Mira si se '
    + 'referia a otra cosa —«unos 15» suele ser XV anos— y si de verdad son '
    + 'sus invitados, diselo: por menos de 50 no hay paquete.');
}

// Escribio un anio que ya paso.
if (p.fecha_pasada) {
  partes.push(`El cliente escribio «${p.fecha_pasada}», que ya paso. `
    + 'Preguntale de que anio es, con tacto: lo mas probable es que se haya '
    + 'equivocado de tecla.');
}

if (p.fecha_larga) {
  partes.push(`La fecha de la que se habla es el ${p.fecha_larga}. `
    + 'Nombrala siempre asi, con su dia de la semana.');
}
if (especial && especial.aviso) {
  partes.push(`Ese dia es ${especial.titulo}. ${especial.aviso} `
    + (especial.se_puede_cotizar
      ? 'Diselo con tus palabras en cuanto hablen de esa fecha, sin esperar a cotizar, '
        + 'y sigue adelante con normalidad: la fecha se vende igual.'
      : 'Esa fecha NO se puede vender.'));
} else if (p.fecha_larga) {
  // El «no» va DICHO, no sobreentendido.
  //
  // Callar cuando la fecha no tiene nada especial parecia suficiente, y no lo
  // es: el cliente pregunto «el 20 de marzo cae en Semana Santa?» y la agente
  // le dijo que si. No lo saco de ningun dato —aqui venia null— sino de la
  // propia pregunta. Un modelo lee el silencio como permiso para seguirle la
  // corriente a quien pregunta, asi que el silencio se acabo.
  partes.push('Ese dia NO es Semana Santa ni ninguna fecha especial, y no tiene '
    + 'nada que avisar. Si el cliente da por hecho que si, corrigelo.');
}

return [{
  json: {
    // Todo lo de armar_patch sigue viaje: `hay_datos` y `guardar_en_kommo`
    // leen de aqui.
    ...p,
    fecha_especial: especial,
    nota_fecha: partes.length ? '\n\n[Sistema] ' + partes.join(' ') : '',
  },
}];
